/** Presents ordered architecture steps with reduced-motion-aware reveals. */
export function ArchitectureFlow({ flow }: Readonly<{ flow: Flow }>) {
  const reduced = useReducedMotion();
  return (
    <div className="flow-block">
      <h4>{flow.title}</h4>
      <ol className="architecture-flow">
        {flow.steps.map((step, index) => (
          <motion.li
            key={step}
            initial={reduced ? false : { opacity: 0, y: 12 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: index * .055 }}
          >
            <span className="flow-number">{String(index + 1).padStart(2, '0')}</span>
            <span>{step}</span>
            {index < flow.steps.length - 1 && (
              <ArrowRight className="flow-arrow" size={14} aria-hidden="true" />
            )}
          </motion.li>
        ))}
      </ol>
    </div>
  );
}

