/** Renders a labeled concept preview with optional local search and bookmarking. */
export function NewsVisual({ interactive = false }: Readonly<{ interactive?: boolean }>) {
  const [category, setCategory] = useState('For you');
  const [query, setQuery] = useState('');
  const [saved, setSaved] = useState<number[]>([]);
  const filtered = articles.filter(a => (
    category === 'For you' || (category === 'Saved' ? saved.includes(a.id) : a.category === category)
  ) && `${a.title} ${a.category}`.toLowerCase().includes(query.toLowerCase()));
  return (
    <div className={`news-visual visual-inner ${interactive ? 'is-interactive' : ''}`}>
      <div className="news-top">
        <span className="news-wordmark">the daily<span>.</span></span>
        <span className="news-concept">NEWSAPP / CONCEPT PREVIEW</span>
      </div>
      <div className="news-navigation">
        {['For you', 'Technology', 'Science', 'Business', 'Saved'].map(c => interactive ? (
          <button
            key={c}
            aria-pressed={category === c}
            onClick={() => setCategory(c)}
            className={category === c ? 'chosen' : ''}
          >
            {c}
          </button>
        ) : <span key={c} className={c === 'For you' ? 'chosen' : ''}>{c}</span>)}
      </div>
      <div className="news-title-row">
        <div>
          <span className="mono-label">A LITTLE CURIOSITY GOES A LONG WAY.</span>
          <h4>Your world. In focus.</h4>
        </div>
        {interactive ? (
          <label className="news-search">
            <Search size={15} />
            <input
              aria-label="Search concept stories"
              placeholder="Search stories"
              value={query}
              onChange={e => setQuery(e.target.value)}
            />
          </label>
        ) : <Search size={19} />}
      </div>
      <div className="news-articles">
        {filtered.map(a => (
          <article className="news-article" key={a.id}>
            <div className={`news-art ${a.art}`} aria-hidden="true"><i /><i /><i /></div>
            <div className="news-article-meta">
              <span>{a.category}</span>
              {interactive ? (
                <button
                  className="bookmark-button"
                  aria-label={`${saved.includes(a.id) ? 'Remove bookmark for' : 'Bookmark'} ${a.title}`}
                  aria-pressed={saved.includes(a.id)}
                  onClick={() => setSaved(prev => (
                    prev.includes(a.id) ? prev.filter(id => id !== a.id) : [...prev, a.id]
                  ))}
                >
                  <Bookmark size={14} fill={saved.includes(a.id) ? 'currentColor' : 'none'} />
                </button>
              ) : <Bookmark size={13} />}
            </div>
            <h5>{a.title}</h5>
            <span className="news-article-label">{a.label}</span>
          </article>
        ))}
      </div>
      {/* Preserve the previous paragraph's block layout so the existing empty-state spacing applies. */}
      {filtered.length === 0 && (
        <output className="news-empty" style={{ display: 'block' }}>
          {category === 'Saved'
            ? 'Bookmark a concept story to see it here.'
            : 'No concept stories match this search.'}
        </output>
      )}
      <div className="visual-caption">
        ILLUSTRATIVE CONTENT · NOT AN ORIGINAL APP SCREENSHOT{interactive && ' · INTERACTIVE DEMO'}
      </div>
    </div>
  );
}

/** Displays supplied screenshots unchanged, otherwise falling back to clearly labeled illustrations. */
export function ProjectVisual({ project, interactive = false }: Readonly<{
  project: Project;
  interactive?: boolean;
}>) {
  const image = project.screenshots[0];
  if (image) {
    return (
      <figure className="real-screenshot">
        <img src={image.src} alt={image.alt} loading="lazy" decoding="async" />
        <figcaption>{image.caption}</figcaption>
      </figure>
    );
  }
  if (project.id === 'studymate') {
    return <StudyVisual />;
  }
  if (project.id === 'pizzeria') {
    return <PizzaVisual />;
  }
  return <NewsVisual interactive={interactive} />;
}